div.script:
(function () {
    function openM(id){ var m=document.getElementById(id); if(m) m.classList.add("open"); }
    function closeM(id){ var m=document.getElementById(id); if(m) m.classList.remove("open"); }
    document.querySelectorAll("[data-close-modal]").forEach(function(b){
        b.addEventListener("click", function(){ closeM(b.getAttribute("data-close-modal")); });
    });
    ["ucModal","ucDelModal"].forEach(function(id){
        var m=document.getElementById(id);
        if(m){ m.addEventListener("click", function(e){ if(e.target===m) closeM(id); }); }
    });
    var form=document.getElementById("ucForm");
    var addBtn=document.querySelector(".uc-add-btn");
    if(addBtn&&form){ addBtn.addEventListener("click", function(){
        document.getElementById("ucModalTitle").textContent="Agregar certificado";
        form.action="/marketplace/mis-certificados/agregar";
        document.getElementById("ucCertSelectWrap").style.display="";
        document.getElementById("ucCert").disabled=false;
        document.getElementById("ucCert").value="";
        document.getElementById("ucCertFixed").style.display="none";
        document.getElementById("ucNumber").value="";
        document.getElementById("ucIssue").value="";
        document.getElementById("ucExpiry").value="";
        document.getElementById("ucFile").value="";
        document.getElementById("ucFileReq").style.display="";
        document.getElementById("ucFileHint").textContent="";
        openM("ucModal");
    }); }
    document.querySelectorAll(".uc-edit-btn").forEach(function(b){ if(!form) return; b.addEventListener("click", function(){
        document.getElementById("ucModalTitle").textContent="Editar / renovar certificado";
        form.action="/marketplace/mis-certificados/"+b.getAttribute("data-id")+"/renovar";
        // El tipo de certificado no cambia al renovar: se muestra fijo.
        var sel=document.getElementById("ucCert");
        sel.value=b.getAttribute("data-cert")||""; sel.disabled=true;
        document.getElementById("ucCertFixed").textContent=b.getAttribute("data-certname")||"";
        document.getElementById("ucCertFixed").style.display="";
        document.getElementById("ucNumber").value=b.getAttribute("data-number")||"";
        document.getElementById("ucIssue").value=b.getAttribute("data-issue")||"";
        document.getElementById("ucExpiry").value=b.getAttribute("data-expiry")||"";
        document.getElementById("ucFile").value="";
        document.getElementById("ucFileReq").style.display="none";
        document.getElementById("ucFileHint").textContent="Deja vacío para conservar el archivo actual.";
        openM("ucModal");
    }); });
    var delForm=document.getElementById("ucDelForm");
    document.querySelectorAll(".uc-del-btn").forEach(function(b){ if(!delForm) return; b.addEventListener("click", function(){
        delForm.action="/marketplace/mis-certificados/"+b.getAttribute("data-id")+"/eliminar";
        document.getElementById("ucDelName").textContent=b.getAttribute("data-name")||"";
        openM("ucDelModal");
    }); });
})();

(function(){
  function init(){
    // Toggle capacidad: dimensiones vs volumen directo
    var mode=document.getElementById("sfPondMode");
    if(mode){
      var dims=document.querySelectorAll(".sf-pond-dims");
      var vol=document.querySelectorAll(".sf-pond-vol");
      var applyMode=function(){
        var isVol=mode.value==="volume";
        dims.forEach(function(d){ d.style.display=isVol?"none":""; });
        vol.forEach(function(v){ v.style.display=isVol?"":"none"; });
      };
      mode.addEventListener("change",applyMode);
      applyMode();
    }

    // ---- Modales de instalación / piscina ----
    function openM(id){ var m=document.getElementById(id); if(m) m.classList.add("open"); }
    function closeM(id){ var m=document.getElementById(id); if(m) m.classList.remove("open"); }
    document.querySelectorAll("[data-close-modal]").forEach(function(b){
      b.addEventListener("click", function(){ closeM(b.getAttribute("data-close-modal")); });
    });
    ["facModal","pondModal"].forEach(function(id){
      var m=document.getElementById(id);
      if(m){ m.addEventListener("click", function(e){ if(e.target===m) closeM(id); }); }
    });
    var facForm=document.getElementById("facForm");
    var facNew=document.querySelector(".fac-new-btn");
    if(facNew&&facForm){ facNew.addEventListener("click", function(){
      document.getElementById("facModalTitle").textContent="Nueva instalación";
      facForm.action="/marketplace/mis-instalaciones/facility/crear";
      document.getElementById("facName").value="";
      document.getElementById("facType").value="farm";
      document.getElementById("facCity").value="";
      document.getElementById("facCode").value="";
      document.getElementById("facAddress").value="";
      openM("facModal");
    }); }
    var facEdit=document.querySelector(".fac-edit-btn");
    if(facEdit&&facForm){ facEdit.addEventListener("click", function(){
      document.getElementById("facModalTitle").textContent="Editar instalación";
      facForm.action="/marketplace/mis-instalaciones/facility/"+facEdit.getAttribute("data-id")+"/actualizar";
      document.getElementById("facName").value=facEdit.getAttribute("data-name")||"";
      document.getElementById("facType").value=facEdit.getAttribute("data-type")||"farm";
      document.getElementById("facCity").value=facEdit.getAttribute("data-city")||"";
      document.getElementById("facCode").value=facEdit.getAttribute("data-code")||"";
      document.getElementById("facAddress").value=facEdit.getAttribute("data-address")||"";
      openM("facModal");
    }); }
    var pondForm=document.getElementById("pondForm");
    function setPondMode(v){ var el=document.getElementById("sfPondMode"); if(el){ el.value=v; el.dispatchEvent(new Event("change")); } }
    var pondNew=document.querySelector(".pond-new-btn");
    if(pondNew&&pondForm){ pondNew.addEventListener("click", function(){
      document.getElementById("pondModalTitle").textContent="Nueva piscina";
      pondForm.action="/marketplace/mis-instalaciones/pond/crear";
      document.getElementById("pondName").value="";
      document.getElementById("pondType").value="earth";
      ["pondLen","pondWid","pondDep","pondVol","pondLoc"].forEach(function(i){ var el=document.getElementById(i); if(el) el.value=""; });
      var h=document.getElementById("pondImgHint"); if(h) h.textContent="(opcional)";
      setPondMode("dimensions");
      openM("pondModal");
    }); }
    document.querySelectorAll(".pond-edit-btn").forEach(function(b){ if(!pondForm) return; b.addEventListener("click", function(){
      document.getElementById("pondModalTitle").textContent="Editar piscina";
      pondForm.action="/marketplace/mis-instalaciones/pond/"+b.getAttribute("data-id")+"/actualizar";
      document.getElementById("pondName").value=b.getAttribute("data-name")||"";
      document.getElementById("pondType").value=b.getAttribute("data-type")||"earth";
      document.getElementById("pondLen").value=b.getAttribute("data-length")||"";
      document.getElementById("pondWid").value=b.getAttribute("data-width")||"";
      document.getElementById("pondDep").value=b.getAttribute("data-depth")||"";
      document.getElementById("pondVol").value=b.getAttribute("data-volume")||"";
      document.getElementById("pondLoc").value=b.getAttribute("data-location")||"";
      var h=document.getElementById("pondImgHint"); if(h) h.textContent="(deja vacío para conservar la actual)";
      setPondMode(b.getAttribute("data-mode")||"dimensions");
      openM("pondModal");
    }); });

    var modal=document.getElementById("sfConfirm");
    var form=document.getElementById("sfDelForm");
    if(!modal||!form) return;
    var msg=document.getElementById("sfConfirmMsg");
    var ok=document.getElementById("sfConfirmOk");
    var cancel=document.getElementById("sfConfirmCancel");
    var pending=null;
    function open(url,text){ pending=url; if(msg&&text){ msg.textContent=text; } modal.classList.add("open"); }
    function close(){ modal.classList.remove("open"); pending=null; }
    document.querySelectorAll(".sf-del-btn").forEach(function(b){
      b.addEventListener("click",function(){ open(b.getAttribute("data-url"), b.getAttribute("data-msg")); });
    });
    if(ok){ ok.addEventListener("click",function(){ if(pending){ form.action=pending; form.submit(); } }); }
    if(cancel){ cancel.addEventListener("click",close); }
    modal.addEventListener("click",function(e){ if(e.target===modal){ close(); } });
    document.addEventListener("keydown",function(e){ if(e.key==="Escape"){ close(); } });
  }
  if(document.readyState==="loading"){ document.addEventListener("DOMContentLoaded",init); } else { init(); }
})();
